insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bbed5acf-47e7-481b-a5b7-1d6b9eb91fd9', 'fr', 'Avant d’aborder, la pensée « Elle ne va pas m’apprécier » surgit. Meilleure réaction ?', '["La reconnaître comme une peur automatique, puis aborder quand même", "La contester en listant les raisons pour lesquelles elle pourrait t’apprécier", "T’en servir comme motivation pour améliorer ta technique", "Attendre que la pensée passe avant d’aborder"]'::jsonb, 'Cette pensée est une peur automatique, pas un signal d’arrêt. Aborde quand même.')
