insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7547b293-5e2d-432b-91d9-4b652d3472a7', 'fr', 'Tu te repasses une conversation et tu te construis une histoire critique sur toi. Que dois-tu remarquer ?', '["Cette histoire est une preuve factuelle", "Il faut couper ce film tout de suite", "Tu dois corriger chaque défaut perçu", "Ton esprit comble les vides avec de la peur, pas avec des faits"]'::jsonb, 'Par défaut, l’esprit comble les vides avec de la peur ; en prendre conscience brise ce schéma.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d5706755-0591-489f-9b13-9ec5811a5057', 'fr', 'Après une approche, une pensée te dit « J’ai eu l’air gauche ». Que fais-tu ?', '["L’accepter comme une preuve et te repasser le moment", "La laisser définir l’image que tu as de toi", "Argumenter contre cette pensée pour la faire taire", "La remarquer comme un bruit de fond sans la croire"]'::jsonb, 'Tu ne contrôles pas les pensées qui surgissent, mais tu contrôles le fait de les croire ou non.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('70a9bde6-01ce-4b79-a9e2-97efa1252a1d', 'fr', 'Que reflète généralement un rejet ?', '["Le niveau de confort de l’autre personne", "Tes erreurs dans la façon de faire", "Un manque d’attirance", "Un échec social"]'::jsonb, 'La plupart des reculs sont une protection, pas un jugement.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4792cc41-039e-460b-9a94-6f1fdb50ceb7', 'fr', 'Où se trouve la vraie confiance en soi après un rejet ?', '["Dans le fait de rester entier quand on ne veut pas de toi", "Dans le fait d’éviter tout rejet", "Dans l’approbation de tout le monde", "Dans le fait de rattraper chaque recul"]'::jsonb, 'La confiance en soi, c’est rester stable quelles que soient les réactions des autres.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('db69db01-07df-42b3-8e90-41a34457e803', 'fr', 'Après une courte discussion, elle prend poliment congé. Que dois-tu en conclure ?', '["Tu as dit quelque chose de travers et tu as échoué", "Ta valeur a été jugée insuffisante", "Elle protégeait son propre confort, ou ce n’était pas le moment", "Tu dois insister pour rattraper le coup"]'::jsonb, 'Un rejet est généralement une protection, pas un verdict sur toi.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e37e687b-c171-4e4a-b17d-9ae50f0a2b9f', 'fr', 'Qu’est-ce qui abîme vraiment la confiance après un mauvais moment ?', '["L’histoire que tu te répètes, pas le moment lui-même", "La façon dont les autres ont perçu la scène et y ont réagi", "La gravité réelle et le côté gênant de l’événement"]'::jsonb, 'Le problème n’est pas le moment, mais le souvenir que tu continues de te repasser.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('43e16323-ce86-4e7f-9c28-27d04a6dcc33', 'fr', 'Quel pouvoir as-tu sur tes expériences passées ?', '["Les effacer complètement", "Empêcher tout moment gênant à l’avenir", "Forcer les autres à les oublier", "Choisir le sens et l’histoire que tu en gardes"]'::jsonb, 'Ton regard fait de toi l’auteur : réécris l’histoire pour te libérer du bruit négatif.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b74e3d6f-b4f5-4f7f-a9fe-edc477912533', 'fr', 'Un homme attend de se sentir sûr de lui avant d’aborder. Quel est le problème ?', '["La confiance vient des preuves ; attendre la retarde", "Il devrait d’abord travailler ses croyances intérieures", "Il a besoin de plus de préparation mentale avant d’agir"]'::jsonb, 'L’esprit se fie aux preuves concrètes de l’action. Le courage vient en premier, la confiance ensuite.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b8219bd4-82ca-488f-a68f-22ee4942c702', 'fr', 'Qu’est-ce qui prouve que la confiance se construit ?', '["Prendre la parole malgré l’hésitation", "Soutenir un regard une seconde de plus que ce qui te met à l’aise", "Attendre de te sentir prêt", "Aller jusqu’au bout quand il serait plus facile d’abandonner"]'::jsonb, 'Les preuves viennent du fait d’agir malgré l’inconfort.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('12f0ca40-33ce-4e67-bffb-cfc678a28f97', 'fr', 'Un homme aborde malgré son hésitation. Qu’enregistre son cerveau ?', '["« Je l’ai fait quand même » devient la preuve qu’il en est capable", "« J’ai surmonté ma peur », ce qui renforce sa résilience mentale avec le temps", "« J’ai été courageux », ce qui renforce une image positive de lui-même", "Toutes les réponses ci-dessus"]'::jsonb, 'Ce sont tous des bénéfices pour lui, qui augmentent ses chances d’aborder à nouveau.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b0b79ba6-0f99-427a-8b41-59a2b41ccda1', 'fr', 'Qu’est-ce qui prédit le mieux les progrès en compétences sociales ?', '["La persévérance à travers une pratique répétée", "Le talent naturel et l’intelligence sociale de départ", "La qualité de l’enseignement et de l’accompagnement reçus"]'::jsonb, 'Les progrès viennent de la pratique accumulée avec le temps.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d3e5a977-5717-4d10-aebd-1477b55d9977', 'fr', 'Deux hommes vivent un échange gênant. L’un réessaie, l’autre arrête. Qu’est-ce qui les différencie ?', '["L’un en a conclu qu’il manquait de pratique ; l’autre, qu’il manquait de talent", "L’un a des compétences sociales naturelles, l’autre non", "L’un avait de meilleures techniques et de meilleures bases"]'::jsonb, 'La différence tient à la conclusion qu’ils en ont tirée, pas à l’échange lui-même.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f9d8c142-995d-43f7-81fe-a5b493c6b7af', 'fr', 'Quelles croyances reflètent un état d’esprit de développement ?', '["Les compétences peuvent progresser", "L’effort mène quelque part", "L’échec définit tes capacités"]'::jsonb, 'On continue d’apprendre quand on croit que ses capacités peuvent grandir.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2b35fc5b-fbe7-4df2-9a70-b1ba3a8b77b9', 'fr', 'Pourquoi éviter d’agir augmente-t-il la peur avec le temps ?', '["La confiance s’estompe", "La mémoire exagère", "Le risque paraît plus grand", "Le corps apprend que l’évitement est sans danger"]'::jsonb, 'Chaque évitement renforce la réaction de peur du corps.')
