insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('39115a96-71ac-4675-991c-cb9189cd877a', 'fr', 'Quel effet l’autosurveillance a-t-elle sur ta présence ?', '["Elle renforce un lien authentique", "Elle te fait passer de l’expression au rôle que tu joues", "Elle tourne ton attention vers l’intérieur plutôt que vers l’extérieur"]'::jsonb, 'S’observer sans cesse sape le sang-froid et le naturel.')
