insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7a7a2960-2b38-4259-9599-598cc15e9937', 'fr', 'Pourquoi une respiration lente réduit-elle efficacement la peur ?', '["Elle contredit directement les pensées négatives", "Elle signale la sécurité au système nerveux", "Elle ralentit le cœur et éclaircit l’esprit"]'::jsonb, 'Ralentir ton expiration dit à ton système nerveux qu’il n’y a aucune menace à gérer.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('013f4dc3-e950-4940-9fab-7657d9decb9b', 'fr', 'Comment l’ancrage interrompt-il les pensées qui tournent en boucle ?', '["En changeant le sens des choses", "En déplaçant l’attention vers les sensations", "En augmentant la concentration", "En étouffant l’émotion"]'::jsonb, 'L’ancrage fonctionne en sortant l’attention de la tête pour la ramener aux sensations physiques.')
