insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('55639c7a-b396-4a1c-ae26-431442cfe270', 'fr', 'Que signale d’abord un sourire sincère ?', '["L’attirance", "L’assurance", "La sécurité et la chaleur", "Le jeu"]'::jsonb, 'Un sourire est perçu instantanément comme rassurant. Il t’aide avant même les premiers mots.')
