insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2886592f-4bba-4b7d-bcfc-6547f1eb778e', 'fr', 'Comment un sourire sincère crée-t-il une réaction positive chez les deux personnes ?', '["Il signale une menace au système nerveux", "Il améliore l’humeur et réduit le stress, neurologiquement", "Le cerveau reproduit inconsciemment l’émotion positive"]'::jsonb, 'Sourire déclenche des sensations positives partagées avant même que la conversation commence.')
